import{z as l,x as s,o as B,c as d,q as i,j as r,D as A,d as a,s as t,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"可复现的计算环境","description":"","frontmatter":{"title":"可复现的计算环境","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ec-reproducible-computing.md","filePath":"econ/ec-reproducible-computing.md","lastUpdated":1791063341000}'),p={name:"econ/ec-reproducible-computing.md"};function c(m,E,u,D,h,C){const n=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=i('<h1 id="可复现的计算环境" tabindex="-1">可复现的计算环境 <a class="header-anchor" href="#可复现的计算环境" aria-label="Permalink to &quot;可复现的计算环境&quot;">​</a></h1><div class="epigraph"><p>关于计算科学的论文不是学术成果本身，只是广告；成果是生成那些图表的完整软件环境与全部指令。</p><footer>—— Claerbout 的表述，转引自 Peng, Reproducible Research in Computational Science, Science 2011</footer></div><p><a href="/econ/ec-bigdata-survey-fusion">上一课</a>把两源组合钉成估计问题；这一课换层：得到估计之后，别人——包括半年后的你自己——能不能重新得到同一个数。<a href="/econ/pm-specification-map">实证规范课</a>已把复现三件套列为规范的一格；本课把那一格展开成完整工程。前三课的口径、协议、链接若不能冻结下来，全部白费：复现是数据纪律的落袋方式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实证结果是代码、数据、环境三者的合取，任何一角漂移，结果就动。软件版本改变数值：优化器路径、随机数实现、默认方法都在变。数据修订改写历史：今天的公开序列不再等于写作那天的 vintage，<a href="/econ/ec-data-sources">第一课</a>的口径五查若没留快照，回放无从谈起。隐式自由度散落在代码里：样本过滤、异常值处理、聚类层级、并行归约次序。这不是新患：Dewald–Thursby–Anderson 1986 的《货币、信贷与银行杂志》复制项目发现，交付的数据与代码普遍无法原样重跑；Chang–Li 2015 用独立代码复算六十六篇论文，约半数结果对不上。</p><h3 id="最小复现包" tabindex="-1">最小复现包 <a class="header-anchor" href="#最小复现包" aria-label="Permalink to &quot;最小复现包&quot;">​</a></h3><p><span class="marginnote">Chang 与 Li 2015 的标题即结论：六十六篇「成功了一半」。失败多不在算法，而在未记录的自由度——样本过滤、清洗规则、口径选择。钉死这些自由度，比换任何统计软件都重要。</span></p><p>一个复现包最少五件。数据快照：原始数据只读存档，附点-in-time 标记。代码：唯一入口、随机数种子固定、禁止交互输入。环境锁：依赖清单或容器镜像，把「能跑」钉在环境定义上而不是某台机器上。<span class="marginnote">术语翻译：环境锁就是把「在哪些软件的哪些版本下跑出来的」写成一串机器可读的清单，或打包成容器镜像。容器可以想成一台连操作系统都打包带走的一次性机器——搬到任何电脑上行为都一样，不再依赖「我机器上明明能跑」。</span>一命令重跑：make 目标或管线 DAG，中间产物全部可再生。结果哈希：对每张表、每幅图做指纹，任何一环被改动都能检出。写作层用 literate 方式把叙述与执行绑在同一份源里（Knuth 1984 是源头）；Gentzkow–Shapiro 2014 的实践指南把这套纪律翻译成社会科学工作流。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',9)),(B(),r(o,null,{default:A(()=>[t(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%3A%20%E5%8F%AA%E8%AF%BB%20%2B%20vintage%20%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20RUN%5B%22%E5%94%AF%E4%B8%80%E5%85%A5%E5%8F%A3%E8%84%9A%E6%9C%AC%3A%20%E7%A7%8D%E5%AD%90%E5%9B%BA%E5%AE%9A%22%5D%0A%20%20ENV%5B%22%E7%8E%AF%E5%A2%83%E9%94%81%3A%20%E4%BE%9D%E8%B5%96%E6%B8%85%E5%8D%95%2F%E5%AE%B9%E5%99%A8%22%5D%20--%3E%20RUN%0A%20%20RUN%20--%3E%20OUT%5B%22%E4%B8%AD%E9%97%B4%E4%BA%A7%E7%89%A9%E5%8F%AF%E5%86%8D%E7%94%9F%22%5D%0A%20%20OUT%20--%3E%20HASH%5B%22%E7%BB%93%E6%9E%9C%E5%93%88%E5%B8%8C%3A%20%E8%A1%A8%E4%B8%8E%E5%9B%BE%E7%9A%84%E6%8C%87%E7%BA%B9%22%5D%0A%20%20HASH%20--%3E%20OK%7B%22%E4%BB%96%E4%BA%BA%E4%B8%80%E5%91%BD%E4%BB%A4%E8%83%BD%E9%87%8D%E8%B7%91%3F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20DONE%5B%22%E5%8F%AF%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20FIX%5B%22%E7%BC%BA%E5%8F%A3%E5%9C%A8%E5%BF%AB%E7%85%A7%2F%E5%85%A5%E5%8F%A3%2F%E7%8E%AF%E5%A2%83%E4%B9%8B%E4%B8%80%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"次序有讲究：先锁环境再跑代码，否则锁文件里混进临时安装的包；先快照再过滤，过滤后的数据与原始数据并存、附过滤脚本；种子连同并行拓扑一起记录，因为并行归约的加法次序本身影响浮点结果——这些次序信息不属于注释，属于交付物。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("复现性的来源是把自由度钉死。统计自由度要进推断，多重检验的折价见"),e("a",{href:"/econ/multiple-testing-econ"},"多重检验"),a("；计算自由度同样要进交付：种子、迭代次数、收敛容差、并行次序，每少报一项，读者就多背一项。浮点加法不满足结合律，归约次序不同，逐位结果就不同——"),e("span",{class:"marginnote"},"数字实例：二进制浮点里 0.1 + 0.2 不等于 0.3（差约 0.000000000000000055）。大数组求和时加法顺序不同，这类舍入误差累积的位置就不同，结果最后几位可能对不上——所以逐位复现要求连「谁先加谁」都记录在案。"),a("于是工程上区分两个层级：数值复现（容差内一致）与逐位复现（哈希一致）；交付时声明用的是哪个层级，是审计契约的一部分。")],-1)),E[6]||(E[6]=e("p",null,"这两个层级各自要求钉什么、终点在哪汇合，可以分开画一张决策图。",-1)),(B(),r(o,null,{default:A(()=>[t(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E4%BB%96%E4%BA%BA%E9%87%8D%E8%B7%91%E5%90%8C%E4%B8%80%E4%BB%BD%E4%BA%A4%E4%BB%98%E7%89%A9%22%5D%20--%3E%20F%7B%22%E7%BB%93%E6%9E%9C%E8%A6%81%E4%B8%80%E8%87%B4%E5%88%B0%E5%93%AA%E4%B8%80%E5%B1%82%22%7D%0A%20%20F%20--%3E%7C%22%E9%80%90%E4%BD%8D%E5%A4%8D%E7%8E%B0%22%7C%20B%5B%22%E5%93%88%E5%B8%8C%E5%AE%8C%E5%85%A8%E4%B8%80%E8%87%B4%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E9%92%89%E6%AD%BB%3A%20%E7%A7%8D%E5%AD%90%2B%E5%B9%B6%E8%A1%8C%E5%BD%92%E7%BA%A6%E6%AC%A1%E5%BA%8F%2B%E5%BA%93%E7%89%88%E6%9C%AC%22%5D%0A%20%20F%20--%3E%7C%22%E6%95%B0%E5%80%BC%E5%A4%8D%E7%8E%B0%22%7C%20N%5B%22%E5%AE%B9%E5%B7%AE%E5%86%85%E4%B8%80%E8%87%B4%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20N%20--%3E%20N1%5B%22%E5%A3%B0%E6%98%8E%3A%20%E5%AE%B9%E5%B7%AE%E5%A4%9A%E5%A4%A7%2C%20%E5%93%AA%E4%BA%9B%E9%A1%B9%E5%85%81%E8%AE%B8%E6%BC%82%22%5D%0A%20%20B1%20--%3E%20C%5B%22%E4%BA%A4%E4%BB%98%E6%97%B6%E5%86%99%E6%98%8E%E5%B1%82%E7%BA%A7%3A%20%E5%AE%A1%E8%AE%A1%E5%A5%91%E7%BA%A6%E7%9A%84%E4%B8%80%E9%83%A8%E5%88%86%22%5D%0A%20%20N1%20--%3E%20C%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<p>不这么做会错在哪：把「我这边能跑」当复现；版本升级后图表微动却已进出版流程；审稿人要求一处改动，却发现没人能重新生成那张表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>复现不等于正确：独立复算通过只说明「数是这么算出来的」，构念与识别对不对是<a href="/econ/ml-causal-econ">计量课</a>的管辖。<span class="marginnote">常见误区：初学者容易把「复现通过」当「结论验证通过」。独立复算只证明数字确实这么算出来的——口径错、识别错的代码照样可以被一字不差地复现；复现是审计的起点，不是替你检查理论的保姆。</span>保密数据无法公开，退而求其次是在安全环境内的受控复现与代码审查——上一课的进入协议在这里接上。容器与锁文件也不是终点：环境会腐化，镜像要定期重建验证，否则「可复现」只是被推迟的不可复现。协作、评审与跨团队共享是这套环境的组织面，留给收束课排进全景。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结果是代码、数据、环境的合取；复现工程就是钉死三者的自由度。</li><li>最小复现包五件：快照、唯一入口、环境锁、一命令重跑、结果哈希。</li><li>数值复现与逐位复现是两个层级，交付时声明用的是哪个。</li><li>经济学的复现危机有据可查：从 JMCB 复制项目到独立复算半数不符，未记录自由度是主因。</li><li>出处：Peng, <em>Science</em> 2011；Dewald, Thursby and Anderson, <em>AER</em> 1986；Chang and Li, <em>AEA Papers and Proceedings</em> 2015；Christensen and Miguel, <em>JEP</em> 2018；Gentzkow and Shapiro 2014 实践指南。</li></ul>',5))])}const b=l(p,[["render",c]]);export{F as __pageData,b as default};
